// 1. HTTP 200 Başarılı Yanıt Kontrolü
pm.test("HTTP Durumu 200 OK olmalı", function () {
    pm.response.to.have.status(200);
});

// 2. Fallback Kontrolü (Motor çökmeden kuralları işleyebildi mi?)
pm.test("Sistem Fallback'e düşmeden kuralı işledi", function () {
    var res = pm.response.json();
    pm.expect(res.fallback_applied).to.eql(false);
});

// 3. Matematiksel & Finansal Tutarlılık Kontrolü
// (Hangi kural kazanmış olursa olsun tutarlar matematiksel olarak doğru mu?)
pm.test("Matematiksel Tutarlılık: Orijinal = İndirim + Ödenecek", function () {
    var res = pm.response.json();
    var beklenenKalan = Math.max(0, res.orijinal_tutar - res.indirim_tutari);
    
    pm.expect(res.odenecek_tutar).to.eql(beklenenKalan);
    pm.expect(res.odenecek_tutar).to.be.at.least(0);
});

// 4. Kural Eşleşme Bilgisi
pm.test("Uygulanan kural bilgisi dolu dönmeli", function () {
    var res = pm.response.json();
    pm.expect(res).to.have.property('uygulanan_kural_id');
});

pm.test("HTTP 200 OK ve Ödenecek Tutar >= 0 olmalı", function () {
    pm.response.to.have.status(200);
    var res = pm.response.json();
    pm.expect(res.odenecek_tutar).to.be.at.least(0);
});

// 1. Sunucunun isteği kabul etmediğini doğrula (Pydantic genelde 422 döner)
pm.test("Geçersiz enum reddedilmeli (HTTP 422 veya 400)", function () {
    pm.expect(pm.response.code).to.be.oneOf([400, 422]);
});

// 2. Hatanın ödeme yöntemi alanından kaynaklandığını teyit et
pm.test("Hata detayı 'odeme_yontemi' alanını işaret etmeli", function () {
    var res = pm.response.json();
    var responseText = JSON.stringify(res);
    pm.expect(responseText).to.include("odeme_yontemi");
});

// 1. Sunucunun negatif tutarı kabul etmeyip 400 veya 422 döndüğünü doğrula
pm.test("Negatif sepet tutarı reddedilmeli (HTTP 400 veya 422)", function () {
    pm.expect(pm.response.code).to.be.oneOf([400, 422]);
});

// 2. Hata mesajının sepet_tutari alanını işaret ettiğini doğrula
pm.test("Hata sepet_tutari alanından kaynaklanmalı", function () {
    var res = pm.response.json();
    var responseText = JSON.stringify(res);
    pm.expect(responseText).to.include("sepet_tutari");
});

// 1. Durum kodunun 200 OK olduğunu doğrula
pm.test("HTTP Durumu 200 OK olmalı", function () {
    pm.response.to.have.status(200);
});

// 2. Dönen verinin liste (array) olduğunu ve kuralların geldiğini teyit et
pm.test("Kural listesi dolu dönmeli", function () {
    var kurallar = pm.response.json();
    pm.expect(kurallar).to.be.an("array");
    pm.expect(kurallar.length).to.be.above(0);
});

// 3. Kuralların oncelik_sirasi alanına sahip olduğunu doğrula
pm.test("Kurallar öncelik sırası barındırmalı", function () {
    var kurallar = pm.response.json();
    pm.expect(kurallar[0]).to.have.property("oncelik_sirasi");
});

pm.test("OpenAPI Şeması ve Sunucu Aktif (HTTP 200)", function () {
    pm.response.to.have.status(200);
    var res = pm.response.json();
    pm.expect(res.openapi).to.include("3.");
});
